# -*- coding: utf-8 -*-
# (speaker, french, korean); speaker None => stage direction (not a turn)
H, K, C, T = "Hélène", "Karim", "Chloé", "M. Leroux"
D = [
(None, "Mardi 30 juin, 9 h 30. Seize jours après la lettre de Delmas. Dehors, il fait déjà 33 degrés. La météo annonce 38 degrés cet après-midi.", "6월 30일 화요일 오전 9시 30분. 델마스의 편지가 온 지 16일 뒤. 밖은 벌써 33도다. 일기예보는 오후 38도를 알린다."),
(K, "Chef ! Viens voir la chambre froide, vite !", "셰프! 냉장실 좀 빨리 와 봐요!"),
(H, "J'arrive. Qu'est-ce qu'il y a ? Tu es tout blanc.", "가는 중이야. 무슨 일이야? 얼굴이 하얘."),
(K, "Il y a un bip depuis tout à l'heure. Regarde l'écran : onze degrés.", "아까부터 삑삑 소리가 나요. 화면 보세요. 11도예요."),
(H, "Onze ? Elle doit être à trois, quatre au maximum !", "11도? 3도에서 최대 4도여야 하는데!"),
(K, "Je sais. J'ai touché le veau : il est tiède. Le poisson aussi.", "알아요. 송아지 고기를 만져 봤는데 미지근해요. 생선도요."),
(H, "Merde. Depuis combien de temps ça dure ?", "젠장. 얼마나 된 거야?"),
(K, "Je sais pas. Hier soir, elle marchait. Le compresseur ne tourne plus.", "모르겠어요. 어젯밤엔 돌아갔어요. 압축기가 더 이상 안 돌아요."),
(H, "Tu as déjà pris ton deuxième café ?", "두 번째 커피는 마셨어?"),
(K, "Pas du tout, mais là je parle quand même.", "전혀요, 그래도 이럴 땐 말이 나오네요."),
(H, "Parfait. On va avoir besoin de toi. Il faut sauver ce qu'on peut.", "좋아. 네가 필요해. 건질 수 있는 건 건져야 해."),
(None, "Chloé arrive de la salle, un chiffon à la main.", "클로에가 행주를 손에 들고 홀에서 온다."),
(C, "Bonjour ! Pourquoi ça sent le chaud, là-dedans ?", "안녕하세요! 여긴 왜 더운 냄새가 나요?"),
(H, "La chambre froide est en panne, Chloé. Aide-nous à vider les étagères.", "냉장실이 고장났어, 클로에. 선반 비우는 걸 도와줘."),
(C, "En panne ? Mais c'est grave, non ? Avec cette chaleur !", "고장이요? 심각한 거 아니에요? 이 더위에!"),
(K, "Très grave. Prends les bacs de légumes d'abord. Ça, ça résiste.", "아주 심각해. 채소 통부터 들어. 그건 버텨 줘."),
(C, "Je les mets où ? Dans la salle ?", "어디에 놓아요? 홀에요?"),
(H, "Non, dans les deux petits frigos, sous le bar. Et dans les glacières.", "아니, 바 밑의 작은 냉장고 두 개에. 그리고 아이스박스에도."),
(K, "Il faut de la glace. Je fais venir Julien avec des sacs de glaçons.", "얼음이 필요해요. 쥘리앵한테 얼음 봉지를 사 오라고 할게요."),
(H, "Appelle-le. Il doit être au marché. Dis-lui d'en prendre dix sacs.", "전화해. 시장에 있을 거야. 열 봉지 사 오라고 해."),
(K, "Dix sacs, d'accord. Je lui envoie un message vocal.", "열 봉지, 알겠어요. 음성 메시지 보낼게요."),
(C, "Pourquoi quatre degrés ? Qu'est-ce qui se passe au-dessus ?", "왜 4도예요? 그 위로 올라가면 어떻게 돼요?"),
(H, "La chaîne du froid. Au-dessus de quatre degrés, les bactéries se multiplient.", "콜드체인이야. 4도를 넘으면 세균이 불어나."),
(K, "Le poisson, c'est pire. Il doit rester entre zéro et deux degrés.", "생선은 더 심해. 0도에서 2도 사이를 지켜야 해."),
(C, "Alors on ne peut pas servir le cabillaud d'aujourd'hui ?", "그럼 오늘 대구는 못 내놓는 건가요?"),
(H, "Non. Le poisson, la crème, les œufs durs : on jette.", "못 내. 생선, 크림, 삶은 달걀은 다 버려."),
(C, "On jette tout ? Mais c'est de l'argent à la poubelle !", "전부 버려요? 그건 돈을 쓰레기통에 넣는 거잖아요!"),
(H, "Je sais. Mais je ne ferai jamais tomber un client malade pour économiser.", "알아. 하지만 돈 아끼겠다고 손님을 아프게 만들 순 없어."),
(K, "Je note tout ce qu'on jette, pour l'assurance. Quinze kilos de cabillaud.", "보험 때문에 버리는 걸 다 적어 둘게요. 대구 15킬로."),
(H, "Ajoute la crème, le beurre ouvert, la terrine de lundi.", "생크림, 개봉한 버터, 월요일 테린도 추가해."),
(C, "Et le veau pour la blanquette ? Il est encore rose.", "블랑케트용 송아지는요? 아직 분홍빛인데요."),
(K, "Je mets la sonde. Tu vois ? Neuf degrés au cœur de la viande.", "탐침을 꽂아 볼게. 봐? 고기 중심이 9도야."),
(H, "Neuf, c'est trop. Mais si on le fait cuire tout de suite, c'est sûr.", "9도면 너무 높아. 하지만 지금 바로 익히면 안전해."),
(K, "Alors je le fais cuire maintenant. Une blanquette pour ce soir et demain.", "그럼 지금 익힐게요. 오늘 저녁이랑 내일 쓸 블랑케트로요."),
(H, "Bonne idée. Et on la refroidit vite, dans un bac d'eau glacée.", "좋은 생각이야. 그리고 얼음물 통에서 빨리 식히고."),
(C, "Pour cuire de la viande par cette chaleur, vous êtes courageux !", "이 더위에 고기를 익히다니 용감하시네요!"),
(K, "Ici, le four est à cent quatre-vingts, la cuisine à quarante-cinq.", "여기선 오븐이 180도고 주방이 45도야."),
(H, "Ça fait de la bonne soupe. Allez, chacun à son poste.", "근사한 수프가 되겠네. 자, 각자 자리로."),
(None, "10 h 05. Hélène sort son téléphone et appelle le dépanneur.", "10시 5분. 엘렌이 전화기를 꺼내 수리 업체에 전화한다."),
(H, "Allô ? Oui, bonjour. Le Comptoir de Marthe, rue de Saint-Maur... Une chambre froide en panne.", "여보세요? 네, 안녕하세요. 생모르 거리의 르 콩투아 드 마르트인데... 냉장실이 고장났어요."),
(H, "Oui, je sais, tout le monde vous appelle. Mais c'est urgent. J'ai de la marchandise.", "네, 다들 전화하는 거 알아요. 그래도 급해요. 식재료가 있거든요."),
(H, "Onze heures ? Parfait. Je vous attends. Merci beaucoup.", "11시요? 좋아요. 기다릴게요. 정말 감사합니다."),
(K, "Alors ? Il vient quand ?", "그래서요? 언제 온대요?"),
(H, "À onze heures. On a de la chance. Il faut tenir une heure.", "11시에. 운이 좋아. 한 시간만 버티면 돼."),
(C, "Moi, j'ai une idée. Mettre des bouteilles d'eau congelées dans les frigos.", "저한테 생각이 있어요. 냉동한 물병을 냉장고에 넣는 거예요."),
(K, "Ça, c'est malin. Où as-tu appris ça ?", "그거 똑똑하네. 어디서 배웠어?"),
(C, "À l'école ! Le prof dit qu'on appelle ça des « pains de glace ».", "학교에서요! 선생님이 « 얼음 덩어리 »라고 부른다고 했어요."),
(H, "Bravo, Chloé. Vas-y, mets-en un par bac.", "잘했어, 클로에. 가서 통마다 하나씩 넣어."),
(C, "Tout de suite. C'est le premier cours qui sert à quelque chose !", "바로요. 쓸모 있는 첫 수업이네요!"),
(K, "Je l'ai entendu. Ne dis pas ça devant ton prof.", "들었어. 선생님 앞에서는 그런 말 하지 마."),
(None, "Un peu avant 11 h, Julien arrive avec dix sacs de glaçons. On les verse dans les bacs. Le dépanneur frappe à la porte de service.", "11시 조금 전, 쥘리앵이 얼음 열 봉지를 들고 도착한다. 얼음을 통에 쏟는다. 수리 기사가 직원 출입구를 두드린다."),
(T, "Bonjour ! Leroux, dépannage froid. C'est vous qui m'avez appelé ?", "안녕하세요! 냉동 수리의 르루입니다. 전화하신 분이세요?"),
(H, "Oui, c'est moi. Merci d'être venu si vite.", "네, 저예요. 이렇게 빨리 와 주셔서 감사해요."),
(T, "Avec ce soleil, j'ai eu douze appels depuis ce matin. Où est le problème ?", "이 햇볕에 아침부터 전화를 열두 통 받았어요. 문제가 어디죠?"),
(K, "Par ici. L'écran affiche onze degrés. Le compresseur est silencieux.", "이쪽이에요. 화면에 11도라고 떠요. 압축기가 조용해요."),
(T, "Hum. Je regarde le groupe à l'arrière. Il est où, le condenseur ?", "음. 뒤쪽 유닛을 볼게요. 응축기는 어디 있죠?"),
(H, "Dans la cour. Il est sous l'escalier. On ne le touche presque jamais.", "마당이요. 계단 밑에 있어요. 거의 손댄 적이 없어요."),
(None, "Dix minutes plus tard, le technicien revient. Son front est trempé de sueur.", "10분 뒤, 기사가 돌아온다. 이마가 땀으로 흠뻑 젖었다."),
(T, "Madame, j'ai une mauvaise nouvelle et une pire nouvelle.", "사장님, 나쁜 소식이 하나 있고 더 나쁜 소식이 있어요."),
(H, "Commencez par la mauvaise. J'aurai peut-être le courage pour l'autre.", "나쁜 소식부터 하세요. 다른 소식을 들을 용기가 생길지도 모르죠."),
(T, "Le condenseur est complètement encrassé. Poussière, graisse, feuilles. Il n'a pas été nettoyé depuis des années.", "응축기가 완전히 막혔어요. 먼지, 기름때, 나뭇잎. 몇 년째 청소 안 했네요."),
(H, "Et la pire nouvelle ?", "그럼 더 나쁜 소식은요?"),
(T, "À force de forcer, le compresseur a grillé. Il faut le remplacer.", "무리하다 보니 압축기가 타 버렸어요. 교체해야 해요."),
(K, "On ne peut pas le faire réparer ? Juste le bobiner ?", "수리해서 쓸 순 없나요? 코일만 다시 감는다든지요."),
(T, "Pas à ce prix-là. Sur ce modèle, ça ne vaut pas la peine.", "그 가격으론 안 돼요. 이 모델에선 그럴 가치가 없어요."),
(H, "Combien pour le remplacement ? Je veux le chiffre exact.", "교체하는 데 얼마예요? 정확한 금액을 알고 싶어요."),
(T, "Compresseur neuf, gaz, main-d'œuvre : 1 450 € toutes taxes comprises.", "새 압축기, 가스, 인건비 합쳐서 세금 포함 1,450유로입니다."),
(H, "Mille quatre cent cinquante euros. Et un appareil neuf ?", "1,450유로. 새 기계는요?"),
(T, "Entre quatre et cinq mille euros, avec la livraison sous trois semaines.", "4천에서 5천 유로, 배송은 3주 안에요."),
(H, "Trois semaines ? Impossible. Réparez, s'il vous plaît.", "3주요? 불가능해요. 수리해 주세요."),
(T, "D'accord. Je commande la pièce chez mon fournisseur. Je peux revenir à seize heures.", "알겠습니다. 거래처에 부품을 주문할게요. 오후 4시에 다시 올 수 있어요."),
(K, "Seize heures ? Et pour ce midi ? On a quarante couverts réservés.", "4시요? 오늘 점심은요? 40명 예약이 있어요."),
(T, "Pour le midi, rien à faire. Gardez vos glacières, ça tiendra.", "점심은 방법이 없어요. 아이스박스로 버티세요, 괜찮을 거예요."),
(H, "Monsieur Leroux, vous nous faites une facture détaillée ? Pour l'assurance.", "르루 씨, 상세 청구서를 써 주실 수 있나요? 보험 때문에요."),
(T, "Bien sûr. Je vous mets le détail : pièce, gaz, déplacement.", "물론이죠. 부품, 가스, 출장비 내역을 적어 드릴게요."),
(T, "Et je vous conseille de faire nettoyer le condenseur deux fois par an.", "그리고 응축기는 1년에 두 번 청소하시길 권해요."),
(H, "Vous proposez un contrat d'entretien ?", "정비 계약도 있으세요?"),
(T, "Oui, 220 € par an. Deux passages. Ça vous éviterait ça.", "네, 연 220유로에 두 번 방문해요. 이런 일을 막을 수 있어요."),
(H, "Je vais y réfléchir. Aujourd'hui, je n'ai plus le moral.", "생각해 볼게요. 오늘은 기운이 하나도 없네요."),
(T, "Je comprends, madame. Courage. À seize heures.", "이해합니다, 사장님. 힘내세요. 4시에 뵙겠습니다."),
(None, "Le technicien part. Hélène s'appuie contre le mur de la cuisine.", "기사가 떠난다. 엘렌이 주방 벽에 몸을 기댄다."),
(K, "Chef, tu vas bien ? Tu veux un verre d'eau ?", "셰프, 괜찮아요? 물 한 잔 드릴까요?"),
(H, "Mille quatre cent cinquante. Le loyer à cinq mille deux cents. Et maintenant ça.", "1,450. 임대료는 5,200. 그리고 이제 이거까지."),
(K, "Les galères arrivent toutes en même temps, hein ?", "골치 아픈 일들이 한꺼번에 오네요, 그렇죠?"),
(H, "Appelle l'assurance pendant que je règle le service. Le numéro est dans le classeur rouge.", "내가 서비스 준비하는 동안 보험사에 전화해. 번호는 빨간 파일에 있어."),
(K, "J'y vais. Je demande pour le bris de machine et les pertes de marchandises.", "갈게요. 기계 파손이랑 식재료 손실을 문의할게요."),
(None, "Quinze minutes plus tard, Karim revient, un papier à la main.", "15분 뒤, 카림이 종이 한 장을 들고 돌아온다."),
(K, "Alors, pour le bris de machine, c'est couvert. Franchise de 300 €.", "기계 파손은 보장돼요. 자기부담금이 300유로예요."),
(H, "Donc l'assureur rembourse 1 150 €. Et la marchandise ?", "그러니까 보험사가 1,150유로를 돌려주는 거네. 식재료는?"),
(K, "Pas couverte. Il faut une option « denrées », et on ne l'a pas prise.", "보장 안 돼요. « 식재료 » 옵션이 필요한데 우린 안 들었어요."),
(H, "Parfait. Combien on a jeté, au total ?", "정말 좋네. 총 얼마나 버렸지?"),
(K, "J'ai compté : à peu près quatre cent vingt euros de marchandise.", "계산했어요. 식재료로 대략 420유로예요."),
(H, "Donc la panne nous coûte 300 plus 420. Sept cent vingt euros.", "그러니까 이번 고장으로 300 더하기 420, 720유로를 잃는 거야."),
(C, "Plus le remboursement qui arrivera dans un mois, peut-être deux.", "게다가 환급은 한 달, 어쩌면 두 달 뒤에나 와요."),
(H, "Exact. Donc d'abord, je paie les 1 450 € de ma poche.", "맞아. 그러니까 우선 1,450유로는 내 돈으로 내야 해."),
(K, "Chef, qu'est-ce qu'on sert ce midi ? On n'a presque plus rien de frais.", "셰프, 오늘 점심에 뭘 내죠? 신선한 게 거의 없어요."),
(H, "On change l'ardoise. Prends un feutre, Chloé, je te dicte.", "칠판을 바꾸자. 클로에, 마커 가져와, 불러 줄게."),
(C, "Je suis prête. Qu'est-ce qu'on écrit ?", "준비됐어요. 뭘 적어요?"),
(H, "Plus d'œuf mayonnaise, plus de terrine. À la place : gaspacho.", "달걀 마요네즈도 테린도 없어. 대신 가스파초."),
(K, "Le gaspacho, ça se fait sans cuisson. Tomates, concombre, poivron. J'ai tout en cagette.", "가스파초는 불 없이 만들어요. 토마토, 오이, 파프리카. 상자에 다 있어요."),
(H, "Parfait. Ensuite : salade de chèvre chaud, c'est vite fait.", "좋아. 다음은 염소 치즈 샐러드, 금방 되니까."),
(C, "Chèvre chaud, avec cette chaleur ? Les gens vont me regarder bizarrement.", "이 더위에 따뜻한 염소 치즈요? 사람들이 이상하게 쳐다볼 텐데요."),
(H, "Alors on dit « chèvre tiède sur toast, salade croquante ». Ça passe mieux.", "그럼 « 따뜻한 토스트 위 염소 치즈, 아삭한 샐러드 »라고 적자. 더 낫지."),
(K, "Pour les plats : la blanquette froide ? Non. Un poulet rôti, tiède, avec salade.", "메인은요? 차가운 블랑케트? 아니죠. 미지근한 구운 닭과 샐러드요."),
(H, "Oui, poulet et steak-frites. Le steak, il est à l'abri dans la glacière.", "그래, 닭이랑 스테이크 프리트. 스테이크는 아이스박스에 잘 있어."),
(C, "Et en dessert ? Les crèmes brûlées sont au frigo du bar.", "후식은요? 크렘 브륄레는 바 냉장고에 있어요."),
(H, "On garde la crème brûlée, et on ajoute un sorbet citron. Il y en a au congélateur.", "크렘 브륄레는 두고 레몬 소르베를 추가하자. 냉동고에 있어."),
(None, "Au service de midi, la salle est pleine malgré la chaleur. Tout le monde s'évente avec les menus.", "점심 서비스에는 더위에도 홀이 가득 찬다. 모두가 메뉴판으로 부채질을 한다."),
(C, "Chef, la table douze demande un autre verre d'eau. C'est la sixième carafe !", "셰프, 12번 테이블이 물을 또 달래요. 벌써 여섯 번째 물병이에요!"),
(H, "Donne-leur de l'eau avec des glaçons, avec un sourire. C'est gratuit.", "얼음 넣은 물을 웃으면서 갖다 줘. 공짜야."),
(K, "Chef, le gaspacho part vite. Il m'en reste pour six portions.", "셰프, 가스파초가 빨리 나가요. 여섯 인분 남았어요."),
(H, "Fais-en d'autre avec les tomates qui restent. Mixe plus grossier.", "남은 토마토로 더 만들어. 좀 더 굵게 갈아."),
(C, "Un monsieur dit que c'est le meilleur gaspacho de sa vie. Je lui dis merci de votre part ?", "한 손님이 평생 먹어 본 최고의 가스파초래요. 감사 인사를 전할까요?"),
(H, "Oui, dis-lui merci. Et que c'est une panne de frigo qui l'a inspiré.", "그래, 고맙다고 전해. 냉장고 고장이 영감이 됐다는 말도."),
(None, "16 h 10. Le dépanneur a fini. L'écran de la chambre froide affiche 12 degrés, puis 8, puis 5.", "오후 4시 10분. 수리 기사가 작업을 마쳤다. 냉장실 화면에 12도, 8도, 5도가 차례로 뜬다."),
(T, "Voilà, c'est reparti. Elle sera à trois degrés d'ici ce soir.", "자, 다시 돌아가요. 오늘 저녁이면 3도가 될 겁니다."),
(H, "Merci, monsieur Leroux. Je vous règle par virement ?", "고맙습니다, 르루 씨. 이체로 드릴까요?"),
(T, "Comme vous voulez. Voici la facture, détaillée comme vous l'avez demandé.", "편하신 대로요. 요청하신 대로 상세하게 적은 청구서입니다."),
(H, "Parfait. Je garde le papier pour l'assurance. Et pour le contrat d'entretien, je vous appelle.", "좋아요. 보험 때문에 서류는 보관할게요. 정비 계약은 전화드릴게요."),
(None, "19 h. La chambre froide affiche 3 degrés. Karim range les bacs de légumes. Chloé nettoie le sol.", "저녁 7시. 냉장실에 3도가 뜬다. 카림이 채소 통을 정리하고 클로에는 바닥을 닦는다."),
(K, "Trois degrés ! Elle respire enfin. Je range les œufs, on garde le reste dehors un peu.", "3도예요! 드디어 숨을 쉬네요. 달걀부터 넣고 나머지는 잠깐 밖에 둘게요."),
(C, "Je suis épuisée. J'ai l'impression d'avoir fait trois services.", "너무 지쳤어요. 서비스를 세 번 한 것 같아요."),
(H, "Vous avez été formidables, tous les deux. Je n'oublierai pas cette journée.", "너희 둘 정말 대단했어. 오늘을 잊지 않을 거야."),
(K, "Moi non plus. Plus jamais de condenseur sous l'escalier sans entretien.", "저도요. 이제 관리 안 한 응축기를 계단 밑에 두는 일은 절대 없어요."),
(H, "Tu as raison. Je signe le contrat d'entretien demain matin.", "맞아. 내일 아침에 정비 계약에 서명할게."),
(C, "Demain, je mets un thermomètre dans chaque frigo. Et je note la température matin et soir.", "내일 냉장고마다 온도계를 하나씩 넣을게요. 아침저녁으로 온도를 적고요."),
(H, "Excellente idée. Un relevé de température aurait évité la moitié du désordre.", "아주 좋은 생각이야. 온도 기록이 있었다면 혼란의 절반은 막았을 거야."),
(K, "Pas la moitié. Le compresseur aurait grillé quand même, non ?", "절반까진 아니죠. 압축기는 어차피 탔을 거예요, 안 그래요?"),
(H, "Peut-être. Bon, rentrez vous reposer. Demain, on repart de zéro.", "그럴지도. 자, 들어가서 쉬어. 내일 다시 처음부터 시작하자."),
(C, "À demain, chef. Et buvez un grand verre d'eau glacée. Vous en avez besoin.", "내일 봬요, 셰프. 얼음물 한 잔 크게 드세요. 필요하시잖아요."),
]

